// Builds worker/discord-feed.js: one file to paste into the Cloudflare dashboard (no wrangler needed).
// Run: node worker/bundle.js
const fs = require('node:fs');
const path = require('node:path');

const read = (p) => fs.readFileSync(path.join(__dirname, p), 'utf8');
const wrap = (name, src) => `const ${name} = (function () { const module = { exports: {} }; ${'\n'}${src}${'\n'}return module.exports; })();\n`;

function bundle() {
  const main = read('index.mjs')
    .replace("import Calls from '../calls.js';\n", '')
    .replace("import Feed from './feed-core.js';\n", '')
    .replace("import Recent from '../recent.js';\n", '')
    .replace("import AlertsCore from './alerts-core.js';\n", '');
  // alerts-core requires recent.js: inside the bundle it uses the Recent wrapper above it, so its own declaration
  // goes (keeping it would shadow the wrapper and throw "Cannot access 'Recent' before initialization").
  const alerts = read('alerts-core.js').replace(/^\s*const Recent = .*require\('\.\.\/recent\.js'\).*\n/m, '');
  if (/require\(/.test(alerts)) throw new Error('alerts-core.js: an unexpected require() would break the bundle');
  return '// GENERATED by `node worker/bundle.js` from calls.js, recent.js, worker/feed-core.js, worker/alerts-core.js and worker/index.mjs. Do not edit.\n'
    + wrap('Calls', read('../calls.js'))
    + wrap('Recent', read('../recent.js'))
    + wrap('Feed', read('feed-core.js'))
    + wrap('AlertsCore', alerts)
    + main;
}

if (require.main === module) {
  fs.writeFileSync(path.join(__dirname, 'discord-feed.js'), bundle());
  console.log('wrote worker/discord-feed.js');
}
module.exports = { bundle };
